import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

import type { ComposerStarterSuggestion } from 'products/posthog_ai/frontend/api/runner'

import { DEFAULT_NEW_SESSION_SUGGESTIONS } from './newSessionSuggestions'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface newSessionSuggestionsLogicValues {
    source: string
    suggestions: ComposerStarterSuggestion[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface newSessionSuggestionsLogicActions {
    selectSuggestion: (
        suggestion: ComposerStarterSuggestion,
        position: number
    ) => {
        position: number
        suggestion: ComposerStarterSuggestion
    }
    setSuggestions: (
        suggestions: ComposerStarterSuggestion[],
        source: string
    ) => {
        source: string
        suggestions: ComposerStarterSuggestion[]
    }
}

export type newSessionSuggestionsLogicType = MakeLogicType<
    newSessionSuggestionsLogicValues,
    newSessionSuggestionsLogicActions
>

export const newSessionSuggestionsLogic = kea<newSessionSuggestionsLogicType>([
    path(['products', 'tasks', 'spaces', 'newSessionSuggestionsLogic']),
    actions({
        setSuggestions: (suggestions: ComposerStarterSuggestion[], source: string) => ({ suggestions, source }),
        selectSuggestion: (suggestion: ComposerStarterSuggestion, position: number) => ({ suggestion, position }),
    }),
    reducers({
        suggestions: [
            DEFAULT_NEW_SESSION_SUGGESTIONS as ComposerStarterSuggestion[],
            { setSuggestions: (_, { suggestions }) => suggestions },
        ],
        source: ['default' as string, { setSuggestions: (_, { source }) => source }],
    }),
    listeners(({ values }) => ({
        selectSuggestion: ({ suggestion, position }) => {
            posthog.capture('today new session suggestion clicked', {
                suggestion_id: suggestion.id,
                position,
                source: values.source,
            })
        },
    })),
])
